var Lm = 48, Rm = 16, Tm = 20, Bm = 44;
var xa = -0.2, xb = 3.4;
var U = function(x) { return 2*x*x*x - 9*x*x + 12*x; };
var umin = 1e9, umax = -1e9, i, xs, us;
for (i = 0; i <= 200; i++) { xs = xa + (xb-xa)*i/200; us = U(xs); if (us < umin) umin = us; if (us > umax) umax = us; }
var pad = 0.12*(umax-umin); umin -= pad; umax += pad;
var px = function(x) { return Lm + (x-xa)/(xb-xa)*(W-Lm-Rm); };
var py = function(u) { return H-Bm - (u-umin)/(umax-umin)*(H-Tm-Bm); };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(Lm, py(umin)); ctx.lineTo(W-Rm, py(umin)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px(0), Tm); ctx.lineTo(px(0), H-Bm); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("U (J)", 6, Tm + 2);
ctx.fillText("x (m)", W-Rm-34, H-Bm+16);
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) { xs = xa + (xb-xa)*i/200; if (i === 0) ctx.moveTo(px(xs), py(U(xs))); else ctx.lineTo(px(xs), py(U(xs))); }
ctx.stroke();
var mark = function(x, label, dy) {
  ctx.strokeStyle = C.rule; ctx.lineWidth = 1; ctx.setLineDash([3,4]);
  ctx.beginPath(); ctx.moveTo(px(x), py(U(x))); ctx.lineTo(px(x), py(umin)); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(px(x), py(U(x)), 4.5, 0, 6.2832); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(label, px(x) - 18, py(U(x)) + dy);
};
mark(1, "x = 1: hilltop, U'' < 0", -12);
mark(2, "x = 2: valley, U'' > 0", 22);
var arrow = function(x, dir) {
  var y = H - Bm + 26, x1 = px(x), x2 = px(x) + dir*22;
  ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(x1, y); ctx.lineTo(x2, y); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x2, y); ctx.lineTo(x2 - 6*dir, y-4); ctx.lineTo(x2 - 6*dir, y+4); ctx.closePath(); ctx.fill();
};
arrow(0.45, -1); arrow(1.35, 1); arrow(2.45, -1); arrow(3.1, -1);
ctx.fillStyle = C.ink;
ctx.fillText("force = -dU/dx", 6, H - Bm + 30);
out.note = "Flat at x = 1 m and x = 2 m. U'' = 12x - 18, so -6 at the first and +6 at the second.";

var Lm = 48, Rm = 16, Tm = 20, Bm = 34;
var a = p.a, b = p.b, m = p.m;
var U = function(x) { return a*x*x*x*x + b*x*x; };
var x0 = b >= 0 ? 0 : Math.sqrt(-b/(2*a));
var k2 = 12*a*x0*x0 + 2*b;
if (k2 < 0.01) k2 = 0.01;
var w = Math.sqrt(k2/m);
var xb = Math.max(1.6, 1.9*x0), xa = -xb;
var i, xs, us, umin = 1e9, umax = -1e9;
for (i = 0; i <= 200; i++) { xs = xa + (xb-xa)*i/200; us = U(xs); if (us < umin) umin = us; if (us > umax) umax = us; }
var pad = 0.15*(umax-umin) + 0.001; umin -= pad; umax += pad;
var px = function(x) { return Lm + (x-xa)/(xb-xa)*(W-Lm-Rm); };
var py = function(u) { return H-Bm - (u-umin)/(umax-umin)*(H-Tm-Bm); };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(Lm, py(umin)); ctx.lineTo(W-Rm, py(umin)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px(0), Tm); ctx.lineTo(px(0), H-Bm); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("U (J)", 6, Tm + 2);
ctx.fillText("x (m)", W-Rm-34, H-Bm+16);
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) { xs = xa + (xb-xa)*i/200; if (i === 0) ctx.moveTo(px(xs), py(U(xs))); else ctx.lineTo(px(xs), py(U(xs))); }
ctx.stroke();
var A = 0.16*xb;
var half = 3*A;
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5; ctx.setLineDash([4,4]);
ctx.beginPath();
for (i = 0; i <= 80; i++) {
  xs = x0 - half + 2*half*i/80;
  us = U(x0) + 0.5*k2*(xs-x0)*(xs-x0);
  if (us > umax) us = umax;
  if (i === 0) ctx.moveTo(px(xs), py(us)); else ctx.lineTo(px(xs), py(us));
}
ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.rule; ctx.setLineDash([3,4]);
ctx.beginPath(); ctx.moveTo(px(x0), py(U(x0))); ctx.lineTo(px(x0), py(umin)); ctx.stroke();
ctx.setLineDash([]);
var xball = x0 + A*Math.cos(w*t);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px(xball), py(U(xball)) - 5, 6, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("minimum at x = " + x0.toFixed(2), px(x0) - 40, H - Bm + 16);
ctx.fillStyle = C.accent;
ctx.fillText("parabola from U''", Lm + 6, Tm + 2);
out.note = "x0 = " + x0.toFixed(2) + " m,  U'' = " + k2.toFixed(2) + " N/m,  omega = " + w.toFixed(2) + " rad/s,  T = " + (6.2832/w).toFixed(2) + " s";

var Lm = 50, Rm = 18, Tm = 20, Bm = 34;
var L = p.L, E = p.E;
var barrier = function(r) { return L*L/(2*r*r); };
var grav = function(r) { return -1/r; };
var Ueff = function(r) { return barrier(r) + grav(r); };
var r0 = L*L;
var umin0 = Ueff(r0);
if (E < umin0 + 0.005) E = umin0 + 0.005;
var ra = 0.12, rb = 6;
var ulo = -1.05, uhi = 0.55;
var px = function(r) { return Lm + (r-ra)/(rb-ra)*(W-Lm-Rm); };
var py = function(u) { if (u > uhi) u = uhi; if (u < ulo) u = ulo; return H-Bm - (u-ulo)/(uhi-ulo)*(H-Tm-Bm); };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(Lm, py(0)); ctx.lineTo(W-Rm, py(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(Lm, Tm); ctx.lineTo(Lm, H-Bm); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("U (per unit mass)", 6, Tm + 2);
ctx.fillText("r", W-Rm-10, py(0) + 16);
var plot = function(f, colour, dash, width) {
  ctx.strokeStyle = colour; ctx.lineWidth = width; ctx.setLineDash(dash);
  ctx.beginPath();
  var i, rr;
  for (i = 0; i <= 300; i++) { rr = ra + (rb-ra)*i/300; if (i === 0) ctx.moveTo(px(rr), py(f(rr))); else ctx.lineTo(px(rr), py(f(rr))); }
  ctx.stroke(); ctx.setLineDash([]);
};
plot(barrier, C.faint, [4,4], 1.5);
plot(grav, C.faint, [1,3], 1.5);
plot(Ueff, C.figure, [], 2.2);
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(Lm, py(E)); ctx.lineTo(W-Rm, py(E)); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("E", W-Rm-14, py(E) - 6);
ctx.fillStyle = C.ink;
ctx.fillText("centrifugal barrier", px(0.55), py(0.42));
ctx.fillText("-GM/r", px(3.4), py(-0.36));
var disc = 1 + 2*E*L*L;
if (disc < 0) disc = 0;
var s = Math.sqrt(disc);
var rmin, rmax, bound;
if (E < -1e-6) { var q1 = (-1+s)/(2*E), q2 = (-1-s)/(2*E); rmin = Math.min(q1,q2); rmax = Math.max(q1,q2); bound = 1; }
else { rmin = L*L/2; rmax = rb; bound = 0; }
var tick = function(r, label) {
  ctx.strokeStyle = C.rule; ctx.setLineDash([3,4]); ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(px(r), py(Ueff(r))); ctx.lineTo(px(r), H-Bm); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.fillText(label, px(r) - 16, H-Bm+16);
};
tick(rmin, bound ? "r min" : "turn");
if (bound) tick(rmax, "r max");
tick(r0, "circular");
var rr;
if (bound) rr = 0.5*(rmin+rmax) - 0.5*(rmax-rmin)*Math.cos(1.4*t);
else rr = rmin;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px(rr), py(E), 5.5, 0, 6.2832); ctx.fill();
out.note = bound
  ? "bound: turning points at r = " + rmin.toFixed(2) + " and r = " + rmax.toFixed(2) + ", circular orbit at r = " + r0.toFixed(2)
  : "unbound: one turning point at r = " + rmin.toFixed(2) + ", then r grows without limit";
